// §19 WF05 — สรุปเครือข่าย/ทีม จากตัวเลขที่นับได้จริงผ่าน API สำหรับระบบอัตโนมัติ
// ⚠️ /api/members (รายชื่อสมาชิก) บังคับคุกกี้ session → n8n (Bearer CRON_SECRET) เรียกไม่ได้
//    จึงใช้ /api/members/count ที่เปิดให้ระบบอัตโนมัติ และคืน { total, active, withRank }
const res = $json || {};
const total = Number(res.total || 0);
const active = Number(res.active || 0);
const withRank = Number(res.withRank || 0);
const sd = $getWorkflowStaticData('global');
sd.history = Array.isArray(sd.history) ? sd.history : [];
const prev = sd.history.length ? sd.history[sd.history.length - 1] : null;
const snap = { date: new Date().toISOString().slice(0, 10), total, active, withRank };
const growth = prev ? { total: total - prev.total, active: active - prev.active, withRank: withRank - prev.withRank } : null;
const g = (k) => growth ? ((growth[k] > 0 ? '+' : '') + growth[k]) : 'ไม่มีข้อมูลรอบก่อน';
sd.history.push(snap);
if (sd.history.length > 180) sd.history = sd.history.slice(-180);
return [{ json: { total, active, withRank, growth, prevDate: prev ? prev.date : null, dataReady: total > 0,
  headline: 'สมาชิกทั้งหมด ' + total + ' คน · active ' + active + ' · มีระดับ (rank) ' + withRank
    + ' · เทียบรอบก่อน: ทั้งหมด ' + g('total') + ' / active ' + g('active') + ' / มีระดับ ' + g('withRank'),
  note: 'ตัวเลขจาก /api/members/count — รายชื่อรายคนและความลึก/ความกว้างของผังต้องใช้ endpoint ที่ต้องล็อกอิน (ยังไม่เปิดให้ n8n)',
  at: new Date().toISOString() } }];

const log = $json || {};
const t = $('สรุปเครือข่าย + KPI ทีม').first().json;
return [{ json: { ok: log.ok === true, emailed: log.email || 'skipped', total: t.total, active: t.active,
  withRank: t.withRank, growth: t.growth, note: t.note } }];
